import{_ as e,o as a,c as l,a0 as d}from"./chunks/framework.DqMqoJl9.js";const c=JSON.parse('{"title":"IP 地址","description":"","frontmatter":{},"headers":[],"relativePath":"network/3-IP.md","filePath":"network/3-IP.md","lastUpdated":1791573371000}'),i={name:"network/3-IP.md"};function r(n,t,o,s,h,P){return a(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="ip-地址" tabindex="-1">IP 地址 <a class="header-anchor" href="#ip-地址" aria-label="Permalink to &quot;IP 地址&quot;">​</a></h1><h2 id="_1-简介" tabindex="-1">1 简介 <a class="header-anchor" href="#_1-简介" aria-label="Permalink to &quot;1 简介&quot;">​</a></h2><p>IP 地址（Internet Protocol Address）是一种在 Internet 上的给主机编址的方式，也称为网络协议地址。常见的 IP 地址，分为 IPv4 与 IPv6 两大类。2011 年 2 月 3 日 IPv4 位地址分配完毕</p><p>IP 地址编址方案：IP 地址编址方案将 IP 地址空间划分为<code>A、B、C、D、E</code>五类，其中 A、B、C 是基本类，D、E 类作为多播和保留使用</p><h3 id="_1-1-ip-地址转换" tabindex="-1">1.1 IP 地址转换 <a class="header-anchor" href="#_1-1-ip-地址转换" aria-label="Permalink to &quot;1.1 IP 地址转换&quot;">​</a></h3><p>将 IP 地址分成了<code>网络号</code>和<code>主机号</code>两部分，设计者就必须决定每部分包含多少位。网络号的位数直接决定了可以分配的网络数（计算方法 2^网络号位数-2）； 主机号的位数则决定了网络中最大的主机数（计算方法 2^主机号位数-2）。然而，由于整个互联网所包含的网络规模可能比较大，也可能 比较小，最后选择了一种灵活的方案：将 IP 地址空间划分成不同的类别，每一类具有不同的网络号位数和主机号位数。</p><p>TCP/IP 协议需要针对不同的网络进行不同的设置，且每个节点一般需要一个<code>IP地址</code>、一个<code>子网掩码</code>、一个<code>默认网关</code>。不过， 可以通过动态主机配置协议（DHCP），给客户端自动分配一个 IP 地址，避免了出错，也简化了 TCP/IP 协议的设置</p><h2 id="_2-ip-地址类型" tabindex="-1">2 IP 地址类型 <a class="header-anchor" href="#_2-ip-地址类型" aria-label="Permalink to &quot;2 IP 地址类型&quot;">​</a></h2><h3 id="_2-1-公有地址" tabindex="-1">2.1 公有地址 <a class="header-anchor" href="#_2-1-公有地址" aria-label="Permalink to &quot;2.1 公有地址&quot;">​</a></h3><p>公有地址（Public address）由 Inter NIC（Internet Network Information Center 因特网信息中心）负责。这些 IP 地址分配给注册并向 Inter NIC 提出申请的组织机构。通过它直接访问因特网。</p><h3 id="_2-2-私有地址" tabindex="-1">2.2 私有地址 <a class="header-anchor" href="#_2-2-私有地址" aria-label="Permalink to &quot;2.2 私有地址&quot;">​</a></h3><p>私有地址（Private address）属于非注册地址，专门为组织机构内部使用。</p><p>以下列出留用的内部私有地址</p><ul><li>A 类 10.0.0.0--10.255.255.255</li><li>B 类 172.16.0.0--172.31.255.255</li><li>C 类 192.168.0.0--192.168.255.255</li></ul><h2 id="_3-ip-地址分类" tabindex="-1">3 IP 地址分类 <a class="header-anchor" href="#_3-ip-地址分类" aria-label="Permalink to &quot;3 IP 地址分类&quot;">​</a></h2><p>每个 IP 地址包括两个标识码（ID），即网络 ID 和主机 ID。同一个物理网络上的所有主机都使用同一个网络 ID，网络上的一个主机（包括网 络上工作站，服务器和路由器等）有一个主机 ID 与其对应</p><table tabindex="0"><thead><tr><th style="text-align:left;">类别</th><th style="text-align:left;">最大网络数</th><th style="text-align:left;">IP 地址范围</th><th style="text-align:left;">最大主机数</th><th style="text-align:left;">私有 IP 地址范围</th></tr></thead><tbody><tr><td style="text-align:left;">A</td><td style="text-align:left;">126（2^7-2)</td><td style="text-align:left;">0.0.0.0-127.255.255.255</td><td style="text-align:left;">16777214</td><td style="text-align:left;">10.0.0.0-10.255.255.255</td></tr><tr><td style="text-align:left;">B</td><td style="text-align:left;">16384(2^14)</td><td style="text-align:left;">128.0.0.0-191.255.255.255</td><td style="text-align:left;">65534</td><td style="text-align:left;">172.16.0.0-172.31.255.255</td></tr><tr><td style="text-align:left;">C</td><td style="text-align:left;">2097152(2^21)</td><td style="text-align:left;">192.0.0.0-223.255.255.255</td><td style="text-align:left;">254</td><td style="text-align:left;">192.168.0.0-192.168.255.255</td></tr></tbody></table><h2 id="_4-特殊的网址" tabindex="-1">4 特殊的网址 <a class="header-anchor" href="#_4-特殊的网址" aria-label="Permalink to &quot;4 特殊的网址&quot;">​</a></h2><ul><li>每一个字节都为 0 的地址（“0.0.0.0”）对应于当前主机</li><li>IP 地址中的每一个字节都为 1 的 IP 地址（“255．255．255．255”）是当前子网的广播地址</li><li>IP 地址中凡是以“11110”开头的 E 类 IP 地址都保留用于将来和实验使用</li><li>IP 地址中不能以十进制“127”作为开头，该类地址中数字 127．0．0．1 到 127．255．255．255 用于回路测试，如：127.0.0.1 可以代表 本机 IP 地址，用<code>http://127.0.0.1</code>就可以测试本机中配置的 Web 服务器</li><li>网络 ID 的第一个 8 位组也不能全置为“0”，全“0”表示本地网络</li></ul>',19)])])}const f=e(i,[["render",r]]);export{c as __pageData,f as default};
